mapper.select:
select cb.*, c.name AS categoryName b.name ASbrandName,b.logo FROM schema_name.category cb inner join schema_name.category_brand c on c.id = cb.category_id inner join schema_name. brand b on b.id = cb.brand_id
and cb.brand_id = #{brandId}
and cb.category_id = #{categoryId}
and cb.is_deleted = 0
order by cb.id desc
